import type {
  ActivityClass,
  DataSource,
  RecognizedActivity,
  SensorEvent,
} from "@/types/home";
import arubaDay from "@/data/homes/generated/aruba.json";
import milanDay from "@/data/homes/generated/milan.json";

/**
 * One real CASAS day per home with model-recognised activities.
 * Generated by `python -m har.export_dashboard` (run from ml/); see that file
 * for how the model is trained and the day is chosen.
 */
interface ExportedDay {
  date: string;
  model: string;
  trainedOn: string;
  correct: number;
  total: number;
  events: { timestamp: string; sensorId: string; state: string | number }[];
  activityHistory: RecognizedActivity[];
}

export interface RealDay {
  events: SensorEvent[];
  activityHistory: RecognizedActivity[];
  currentActivityId: string | null;
  dataSource: DataSource;
}

function toRealDay(
  raw: ExportedDay,
  dataset: string,
  classes: ActivityClass[],
): RealDay {
  // Use the app's display labels ("Meal Preparation") instead of dataset names.
  const labelOf = (id: string, fallback: string) =>
    classes.find((c) => c.id === id)?.label ?? fallback.replace(/_/g, " ");
  const activityHistory = raw.activityHistory.map((a) => ({
    ...a,
    label: labelOf(a.activityId, a.label),
    annotatedLabel: a.annotatedActivityId
      ? labelOf(a.annotatedActivityId, a.annotatedLabel ?? a.annotatedActivityId)
      : undefined,
  }));
  return {
    events: raw.events as SensorEvent[],
    activityHistory,
    currentActivityId: activityHistory.at(-1)?.id ?? null,
    dataSource: {
      dataset,
      date: raw.date,
      model: raw.model,
      trainedOn: raw.trainedOn,
      correct: raw.correct,
      total: raw.total,
    },
  };
}

export function arubaRealDay(classes: ActivityClass[]): RealDay {
  return toRealDay(arubaDay as ExportedDay, "CASAS Aruba", classes);
}

export function milanRealDay(classes: ActivityClass[]): RealDay {
  return toRealDay(milanDay as ExportedDay, "CASAS Milan", classes);
}
